package localchat;
import java.nio.file.*;import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;

/** Child PDF delivery evidence stays structured; model/task prose cannot create delivery cards. */
public final class AgentArtifactsTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static String request(String name,Object args){return Json.write(Json.obj("model","selected-model","choices",List.of(Json.obj("message",Json.obj("content","","tool_calls",List.of(Json.obj("id","child-call","type","function","function",Json.obj("name",name,"arguments",Json.write(args))))))),"usage",Json.obj("prompt_tokens",100,"completion_tokens",10)));}
 static ChatClient.ToolCall assignment(String task){return new ChatClient.ToolCall("agents","run_agents",Json.obj("tasks",List.of(Json.obj("title","PDF child","task",task))));}
 static Agent.Ui ui(){return new Agent.Ui(){public void text(String text){}public void step(){}public void toolStarted(ChatClient.ToolCall c){}public void toolFinished(ChatClient.ToolCall c,Tools.Result r){}};}
 static Tools tools(Path root,Mcp mcp){return new Tools(new Tools.Context(root,root.resolve("skills"),root.resolve("rules.md"),root.resolve("settings.properties"),Map.of(),null,mcp,PathMap.none(),true,EnumSet.allOf(Tools.Access.class),(a,b)->Tools.Decision.NO),List.of());}
 static Object delivery(Path root,String state,boolean verified){return Json.obj("job_id","a".repeat(32),"status",state,"delivery_verified",verified,"report",root.resolve("RAPPORT.pdf").toString(),"differences_report",root.resolve("Vergelijking_OUD_NIEUW.pdf").toString(),"source_files",List.of(root.resolve("source.pdf").toString()),"artifacts",List.of(Json.obj("path",root.resolve("marked.pdf").toString())));}
 static void pdf(Path path)throws Exception{String content="BT /F1 12 Tf 20 100 Td (Synthetic report) Tj ET";String[] objects={"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 200 200] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>","<< /Length "+content.length()+" >>\nstream\n"+content+"\nendstream","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"};ByteArrayOutputStream bytes=new ByteArrayOutputStream();bytes.writeBytes("%PDF-1.4\n".getBytes(StandardCharsets.US_ASCII));List<Integer> offsets=new ArrayList<>();for(int i=0;i<objects.length;i++){offsets.add(bytes.size());bytes.writeBytes(((i+1)+" 0 obj\n"+objects[i]+"\nendobj\n").getBytes(StandardCharsets.US_ASCII));}int xref=bytes.size();bytes.writeBytes("xref\n0 6\n0000000000 65535 f \n".getBytes(StandardCharsets.US_ASCII));for(int offset:offsets)bytes.writeBytes(String.format(Locale.ROOT,"%010d 00000 n \n",offset).getBytes(StandardCharsets.US_ASCII));bytes.writeBytes(("trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF\n").getBytes(StandardCharsets.US_ASCII));Files.write(path,bytes.toByteArray());}
 static void files(Path root)throws Exception{Files.createDirectories(root);for(String name:List.of("RAPPORT.pdf","Vergelijking_OUD_NIEUW.pdf","marked.pdf","source.pdf"))pdf(root.resolve(name));}
 static void discovery(Path root)throws Exception{
  files(root);var good=delivery(root,"done",true);var expected=List.of(root.resolve("RAPPORT.pdf"),root.resolve("Vergelijking_OUD_NIEUW.pdf"),root.resolve("marked.pdf"));
  check(ReportFiles.discover(Json.write(Json.obj("nested",List.of(good))),root).equals(expected),"nested verified delivery shows report/differences/artifact, not source");
  for(String state:List.of("pending","running","failed","cancelled"))check(ReportFiles.discover(Json.write(Json.obj("nested",delivery(root,state,true))),root).isEmpty(),"nested job state cannot leak through JSON regex "+state);
  check(ReportFiles.discover(Json.write(Json.obj("nested",delivery(root,"done",false))),root).isEmpty(),"unverified nested output hidden");
  check(ReportFiles.discover(Json.write(Json.obj("job_id","","status","done","delivery_verified",true,"report",root.resolve("RAPPORT.pdf").toString())),root).isEmpty(),"empty job id is not proof");
  check(ReportFiles.discover(Json.write(Json.obj("nested",delivery(root,"partial",true))),root).equals(expected),"verified partial delivery preserved honestly");
  check(ReportFiles.discover(Json.write(Json.obj("group_id","fixture","tasks",List.of(Json.obj("task",root.resolve("RAPPORT.pdf").toString(),"answer","Created "+root.resolve("RAPPORT.pdf"),"completed_tools",List.of(Json.obj("result",Json.write(good))))))),root).isEmpty(),"task, answer and opaque tool text are not deliveries");
  check(ReportFiles.discover(Json.write(Json.obj("group_id","fixture","tasks",List.of(Json.obj("deliveries",List.of(Json.obj("report",root.resolve("RAPPORT.pdf").toString())))))),root).isEmpty(),"structured child delivery without job proof is rejected");
  check(ReportFiles.discover(Json.write(Json.obj("task",Json.obj("path",root.resolve("RAPPORT.pdf").toString()),"answer",root.resolve("RAPPORT.pdf").toString())),root).isEmpty(),"structured task input is not output");
  for(String field:List.of("report","file","output","report_path"))check(ReportFiles.discover(Json.write(Json.obj(field,root.resolve("RAPPORT.pdf").toString())),root).equals(List.of(root.resolve("RAPPORT.pdf"))),"generic output JSON remains supported "+field);
  check(ReportFiles.discover("Created: "+root.resolve("RAPPORT.pdf"),root).equals(List.of(root.resolve("RAPPORT.pdf"))),"legacy plain-text output remains supported");
  check(ReportFiles.discover(Json.write(good),root.resolve("elsewhere")).isEmpty(),"workspace boundary preserved");
 }
 static Mcp mock(Path root)throws Exception{
  String python=System.getProperty("agentartifacts.python",Path.of("pdfcontrol/runtime/python/python.exe").toAbsolutePath().toString());Path script=root.resolve("mcp_fixture.py");
  Files.writeString(script,"import json,sys\nfrom pathlib import Path\nfor line in sys.stdin:\n r=json.loads(line)\n if 'id' not in r: continue\n m=r.get('method')\n if m=='initialize': out={'protocolVersion':'2025-06-18','capabilities':{'tools':{}},'serverInfo':{'name':'fixture','version':'1'}}\n elif m=='tools/list': out={'tools':[{'name':'pdfcontrol_job_status','description':'Synthetic receipt','inputSchema':{'type':'object'},'annotations':{'readOnlyHint':True}}]}\n elif m=='tools/call': out={'content':[{'type':'text','text':Path(sys.argv[1]).read_text(encoding='utf-8')}],'isError':False}\n else: out={}\n print(json.dumps({'jsonrpc':'2.0','id':r['id'],'result':out}),flush=True)\n");
  Mcp mcp=new Mcp();mcp.reload(Json.obj("mcpServers",Json.obj("fixture",Json.obj("command",python,"args",List.of("-I","-B",script.toString(),root.resolve("receipt.json").toString()),"cwd",root.toString()))),s->s);check(mcp.servers().size()==1,"synthetic PDF MCP available");return mcp;
 }
 static void groups(Path root)throws Exception{
  files(root);Files.writeString(root.resolve("receipt.json"),Json.write(delivery(root,"done",true)));Mcp mcp=mock(root);
  try{
   for(String state:List.of("done","partial","pending","queued","running","failed","unverified")){
    Files.writeString(root.resolve("receipt.json"),Json.write(delivery(root,state.equals("unverified")?"done":state,!state.equals("unverified"))));
    try(var api=new FeatureTest.Server(FeatureTest.json(request("pdfcontrol_job_status",Json.obj("project","123456","job_id","a".repeat(32)))),FeatureTest.json(FeatureTest.answer("Child final",100,10)))){
     var group=new AgentGroup(()->tools(root,mcp),root.resolve("archives"),65536,1024,false,70);var result=group.run(assignment("Read existing PDF job only"),Provider.CUSTOM,api.url(),"private-fixture-key","selected-model","label","system",ui());List<Path> reports=ReportFiles.discover(result.text,root);boolean valid=state.equals("done")||state.equals("partial");check(valid?reports.size()==3:reports.isEmpty(),"runtime child delivery cards obey verified terminal state "+state);
     if(Set.of("pending","queued","running").contains(state)){Object body=Json.parse(result.text);check("partial".equals(Json.str(body,"tasks",0,"status")),"unfinished PDF task cannot be done "+state);check("a".repeat(32).equals(Json.str(body,"tasks",0,"pending_jobs",0,"job_id")),"pending job id retained for continuation "+state);var field=AgentGroup.class.getDeclaredField("children");field.setAccessible(true);var children=(Set<?>)field.get(group);check(children.size()==1,"completed child retained for later Stop");group.cancel();var stopped=Agent.class.getDeclaredField("cancelled");stopped.setAccessible(true);check(stopped.getBoolean(children.iterator().next()),"parent Stop reaches already-returned child");}
     if(state.equals("partial")||state.equals("unverified")||state.equals("failed"))check(!"done".equals(Json.str(Json.parse(result.text),"tasks",0,"status")),"incomplete PDF result cannot become done "+state);
     if(valid){Object row=Json.get(Json.parse(result.text),"tasks",0);check(((List<?>)Json.get(row,"deliveries")).size()==1,"structured receipt survives child result truncation");check(Files.readString(Path.of(Json.str(row,"archive"))).contains("delivery_verified"),"full receipt retained in private archive");}
    }
   }
   var large=new LinkedHashMap<String,Object>();large.put("padding","x".repeat(5000));large.putAll((Map<String,Object>)delivery(root,"done",true));List<Object> many=new ArrayList<>();for(int i=0;i<22;i++){Path file=root.resolve("marked-many-"+i+".pdf");pdf(file);many.add(Json.obj("path",file.toString()));}large.put("artifacts",many);Files.writeString(root.resolve("receipt.json"),Json.write(large));
   try(var api=new FeatureTest.Server(FeatureTest.json(request("pdfcontrol_job_status",Json.obj("project","123456","job_id","a".repeat(32)))),FeatureTest.json(FeatureTest.answer("Final receipt read",100,10)))){var group=new AgentGroup(()->tools(root,mcp),root.resolve("archives"),65536,1024,false,70);var result=group.run(assignment("Read large verified receipt"),Provider.CUSTOM,api.url(),"","selected-model","label","system",ui());Object row=Json.get(Json.parse(result.text),"tasks",0);check(Boolean.TRUE.equals(Json.get(row,"deliveries_truncated")),"large artifacts explicitly marked truncated");List<Path> discovered=ReportFiles.discover(result.text,root);check(discovered.contains(root.resolve("RAPPORT.pdf"))&&discovered.contains(root.resolve("Vergelijking_OUD_NIEUW.pdf"))&&discovered.size()==18,"primary PDFs preserved with bounded artifact cards");check(Files.readString(Path.of(Json.str(row,"archive"))).contains("marked-many-21.pdf"),"full untruncated artifact receipt in private archive");}
   try(var api=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("Report at "+root.resolve("RAPPORT.pdf"),100,10)))){var group=new AgentGroup(()->tools(root,mcp),root.resolve("archives"),65536,1024,false,70);var result=group.run(assignment("Inspect "+root.resolve("RAPPORT.pdf")),Provider.CUSTOM,api.url(),"","selected-model","label","system",ui());check(ReportFiles.discover(result.text,root).isEmpty(),"model prose and task path alone do not create cards");}
   Files.writeString(root.resolve("receipt.json"),Json.write(delivery(root,"done",true)));
   try(var api=new FeatureTest.Server(FeatureTest.json(request("read_file",Json.obj("path",root.resolve("receipt.json").toString()))),FeatureTest.json(FeatureTest.answer("Read data",100,10)))){var group=new AgentGroup(()->tools(root,mcp),root.resolve("archives"),65536,1024,false,70);var result=group.run(assignment("Read a document"),Provider.CUSTOM,api.url(),"","selected-model","label","system",ui());check(ReportFiles.discover(result.text,root).isEmpty(),"ordinary read_file content cannot impersonate a PDFCONTROL delivery");}
   try(var api=new FeatureTest.Server(FeatureTest.json(request("read_file",Json.obj("path",root.resolve("missing.txt").toString()))),FeatureTest.json(FeatureTest.answer("Visible but blocked final",100,10)))){var group=new AgentGroup(()->tools(root,mcp),root.resolve("archives"),65536,1024,false,70);Object result=Json.parse(group.run(assignment("Read missing input"),Provider.CUSTOM,api.url(),"","selected-model","label","system",ui()).text);check(!"done".equals(Json.str(result,"status"))&&"partial".equals(Json.str(result,"tasks",0,"status")),"tool error plus visible text is partial, not false done");check(Json.str(Json.parse(group.pendingEvidence()),"agent_archive_directory").equals(root.resolve("archives").toString()),"pending evidence identifies actual private archive directory");group.cancel();check("cancelled".equals(Json.str(Json.parse(group.pendingEvidence()),"status")),"Stop pending evidence marks cancellation");}
  }finally{mcp.closeAll();}
 }
 public static void main(String[] args)throws Exception{Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");discovery(home.resolve("discovery"));groups(home.resolve("runtime"));System.out.println("PASS: "+checks+" agent artifact checks; nested verification, structured delivery, actual local files, no prose promotion and partial failures");System.exit(0);}
}
